import React, { useState } from 'react';
import { api } from '../../api/api'; // <-- import nomeado correto

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isRegister, setIsRegister] = useState(false); // alterna entre login e criar conta
  const [message, setMessage] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (isRegister) {
        // Criar conta
        const res = await api.post('/api/auth/register', { email, password });
        setMessage('Conta criada com sucesso! Faça login.');
        setIsRegister(false);
        setEmail('');
        setPassword('');
      } else {
        // Login
        const res = await api.post('/api/auth/login', { email, password });
        setMessage('Login realizado com sucesso!');
        console.log('Token:', res.data.token); // se tiver JWT, salvar aqui
        // Aqui você pode redirecionar para página principal
      }
    } catch (err) {
      console.error(err);
      setMessage(err.response?.data?.message || 'Erro ao autenticar');
    }
  };

  return (
    <div style={{ maxWidth: '400px', margin: '50px auto', textAlign: 'center' }}>
      <h2>{isRegister ? 'Criar Conta' : 'Login'}</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          style={{ display: 'block', width: '100%', margin: '10px 0', padding: '8px' }}
        />
        <input
          type="password"
          placeholder="Senha"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={{ display: 'block', width: '100%', margin: '10px 0', padding: '8px' }}
        />
        <button type="submit" style={{ padding: '10px 20px', marginTop: '10px' }}>
          {isRegister ? 'Criar Conta' : 'Login'}
        </button>
      </form>
      <button
        onClick={() => setIsRegister(!isRegister)}
        style={{ marginTop: '15px', background: 'none', border: 'none', color: 'blue', cursor: 'pointer' }}
      >
        {isRegister ? 'Já tem conta? Login' : 'Criar nova conta'}
      </button>
      {message && <p style={{ marginTop: '15px' }}>{message}</p>}
    </div>
  );
}
